// Pary: zgłoszenie testowe i odpowiedź AI, w tej samej kolejności
const testy = $('Zestaw testowy').all().map(i => i.json);
const odpowiedzi = $input.all().map(i => {
  let ai = i.json.output?.[0]?.content?.[0]?.text;
  if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { ai = null; } }
  return ai || {};
});

let kategorieOk = 0, pilnoscOk = 0;
const pomylki = [];

testy.forEach((t, n) => {
  const ai = odpowiedzi[n];
  const katOk = t.kategorie.includes(ai.kategoria);
  const pilOk = ai.pilnosc === t.pilnosc;
  if (katOk) kategorieOk++;
  if (pilOk) pilnoscOk++;
  if (!katOk || !pilOk) {
    pomylki.push(`#${t.nr} "${t.opis}" | AI: ${ai.kategoria}, ${ai.pilnosc} (pewność ${ai.pewnosc}) | oczekiwane: ${t.kategorie.join(' lub ')}, ${t.pilnosc}`);
  }
});

return [{ json: {
  kategorie: `${kategorieOk}/${testy.length}`,
  pilnosc: `${pilnoscOk}/${testy.length}`,
  zaliczone: kategorieOk >= 17,
  pomylki
}}];
